SELECT id, signal_id, execution_key, side, quantity, price_usdt, decision_price_usdt, execution_price_observed_at AS obs_display, UNIX_TIMESTAMP(execution_price_observed_at) AS obs_epoch, executed_at AS exec_display, UNIX_TIMESTAMP(executed_at) AS exec_epoch, gross_amount_usdt, fee_usdt, realized_pnl_usdt, execution_type, execution_reason, status, LEFT(execution_message,1200) AS msg FROM crypto_ai.wallet_trade WHERE signal_id IN (156723,159408,165412,167668,171589,176710,168277) OR execution_key IN ('POSITION:166:SELL_CONFIRMED','POSITION:172:PROFIT_LOCK_HARD_EXIT','POSITION:187:SELL_CONFIRMED','POSITION:201:HTF_SELL_CONFIRMED','POSITION:211:SELL_CONFIRMED') ORDER BY executed_at LIMIT 20;